mapper.select:
select em.evaluation_material_id as "evaluationMaterialId", em.evaluation_year as "evaluationYear", em.area_code as "areaCode", em.organization_code as "organizationCode", em.target_user_id as "targetUserId", em.source_achievement_id as "sourceAchievementId", em.material_status as "materialStatus", em.deleted_yn as "deletedYn", em.base_score as "baseScore", em.calculated_score as "currentScore", coalesce(latest.participation_type, 'SOLE_AUTHOR') as "participationType", coalesce(latest.distribution_rate, 1.0000) as "distributionRate", coalesce(latest.cap_applied_yn, 'N') as "capAppliedYn", coalesce(latest.generation_no, 0) + 1 as "nextGenerationNo" from evaluation_materials em left join lateral ( select scg.participation_type, scg.distribution_rate, scg.cap_applied_yn, scg.generation_no from score_calculation_generations scg where scg.evaluation_material_id = em.evaluation_material_id order by scg.generation_no desc limit 1 ) latest on true where em.evaluation_year = #{request.evaluationYear} and em.area_code = #{request.areaCode}
and em.target_user_id = #{request.targetUserId}
order by em.evaluation_material_id
